-- Restore The Secrets of Ragefire (map 1131, scenario 219).
-- Spawn, template-state, dialogue, and script data were ported read-only
-- from Legends of Azeroth Pandaria 5.4.8 (build 18414).
-- Legion build 26972 DB2 confirms scenario 219, normal LFG 649, heroic LFG 625,
-- steps 32524/32588/32589/32590 and bonus objective 32799.
START TRANSACTION;

-- Replace any partial population with one coherent source population.
DELETE `ca` FROM `creature_addon` `ca` INNER JOIN `creature` `c` ON `c`.`guid`=`ca`.`guid` WHERE `c`.`map`=1131;
DELETE `wp` FROM `waypoint_data` `wp` INNER JOIN `creature` `c` ON `c`.`guid`=`wp`.`id` WHERE `c`.`map`=1131;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`memberGUID` WHERE `c`.`map`=1131;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`leaderGUID` WHERE `c`.`map`=1131;
DELETE `gec` FROM `game_event_creature` `gec` INNER JOIN `creature` `c` ON `c`.`guid`=`gec`.`guid` WHERE `c`.`map`=1131;
DELETE `pc` FROM `pool_creature` `pc` INNER JOIN `creature` `c` ON `c`.`guid`=`pc`.`guid` WHERE `c`.`map`=1131;
DELETE `geg` FROM `game_event_gameobject` `geg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`geg`.`guid` WHERE `go`.`map`=1131;
DELETE `pg` FROM `pool_gameobject` `pg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`pg`.`guid` WHERE `go`.`map`=1131;
DELETE FROM `creature` WHERE `map`=1131;
DELETE FROM `gameobject` WHERE `map`=1131;



